"""The recorded configuration of the real ogbl-collab rows: configs/collab/collab.yaml (generated by
scripts/make_collab_config.py from the original runs; GCN hyper-parameters, the ISS training config, baseline argv)."""
from functools import lru_cache
from pathlib import Path

import yaml

CONFIG = Path(__file__).resolve().parents[2] / 'configs/collab/collab.yaml'


@lru_cache(maxsize=1)
def config():
    return yaml.safe_load(CONFIG.read_text())
